<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Application\Policy\Allow\Delete;

use Throwable;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Usecase\Delete\ClientIdentityDeleteAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedDeleteAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(ClientIdentityDeleteAllowDecision $proposal): ClientIdentityDeleteAllowDecision
    {
        $this->logDebug("Check IsAuthenticatedDeleteAllow Client identity");
        $span = $this->startSpan("Check IsAuthenticatedDeleteAllow Client identity");
        try {
            $userContext = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (! !$userContext->anonymous) {
                    $proposal->deny('Disabled if not IsAuthenticatedDelete');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
